CREATE TABLE "app"."AccountCharacters" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "app"."AccountCharacters_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"accountId" integer NOT NULL,
	"slot" integer NOT NULL,
	"gameUserName" varchar(200) NOT NULL,
	"createdAt" timestamp (3) DEFAULT now() NOT NULL
);
--> statement-breakpoint
CREATE UNIQUE INDEX "UX_AccountCharacters_account_slot" ON "app"."AccountCharacters" USING btree ("accountId","slot");--> statement-breakpoint
CREATE UNIQUE INDEX "UX_AccountCharacters_gameUserName" ON "app"."AccountCharacters" USING btree ("gameUserName");--> statement-breakpoint
CREATE INDEX "IX_AccountCharacters_accountId" ON "app"."AccountCharacters" USING btree ("accountId");--> statement-breakpoint
-- multi-char: backfill slot 1 = the character every existing account already has today (its own
-- UserName, lowercase — the exact value apps/api/src/routes/auth.ts playConfig already puts in
-- flashvars.user). Idempotent: safe to run again (ON CONFLICT on the (accountId, slot) unique index).
INSERT INTO "app"."AccountCharacters" ("accountId", "slot", "gameUserName")
SELECT "ID", 1, lower("UserName") FROM "member"."Accounts"
ON CONFLICT ("accountId", "slot") DO NOTHING;